INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33561, 'Exodus 29:32', 'Exodus', 29, 32, 'د سپېڅلې خېمې د دروازې په خولې کې دې هارون او د هغه زامن د پسه غوښه او هغه ډوډۍ چې په ټوکرۍ کې پاتې ده، وخوري.', 'د سپېچلې خېمې د دروازې په خولې کې دې هارون او د هغه زامن د پسه غوشه او هغه دودی چې په توکری کې پاتې ده، وخوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33562, 'Exodus 29:33', 'Exodus', 29, 33, 'یوازې هغوی کولای شي چې د ټاکنې په مراسمو کې هغه غوښه او ډوډۍ چې د هغوی د کفارې د ادا کولو دپاره ورڅخه کار اخیستل کیږي، وخوري. عادي خلک نه شي کولای هغه وخوري، ځکه چې دا شیان سپېڅلي دي.', 'یوازې هغوی کولای شی چې د تاکنې په مراسمو کې هغه غوشه او دودی چې د هغوی د کفارې د ادا کولو دپاره ورچخه کار اخیستل کیزی، وخوری. عادی خلک نه شی کولای هغه وخوری، جکه چې دا شیان سپېچلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33563, 'Exodus 29:34', 'Exodus', 29, 34, 'که چېرې یو څه غوښه یا ډوډۍ ونه خوړل شي او تر سهاره پورې پاتې شي، هغه وسوځوه. هغه باید ونه خوړل شي، ځکه چې سپېڅلي دي.', 'که چېرې یو چه غوشه یا دودی ونه خورل شی او تر سهاره پورې پاتې شی، هغه وسوجوه. هغه باید ونه خورل شی، جکه چې سپېچلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33564, 'Exodus 29:35', 'Exodus', 29, 35, 'لکه څنګه چې ما درته حکم کړی دی د هارون او د هغه د زامنو د ټاکنې مراسم دې په اوو ورځو کې سرته ورسیږي.', 'لکه چنګه چې ما درته حکم کری دی د هارون او د هغه د زامنو د تاکنې مراسم دې په اوو ورجو کې سرته ورسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_35.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33565, 'Exodus 29:36', 'Exodus', 29, 36, 'ته باید هره ورځ یو غویی حلال کړې او ماته یې وړاندې کړې، ترڅو د هغوی ګناه وبخښم او د قربانۍ ځای پاک شي. برسېره پردې باید د زیتونو تېل واخلې او د قربانۍ ځای ورباندې مسح کړې چې سپېڅلی شي.', 'ته باید هره ورج یو غویی حلال کرې او ماته یې وراندې کرې، ترچو د هغوی ګناه وبخشم او د قربانی جای پاک شی. برسېره پردې باید د زیتونو تېل واخلې او د قربانی جای ورباندې مسح کرې چې سپېچلی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33566, 'Exodus 29:37', 'Exodus', 29, 37, 'اووه ورځې دا کار وکړه. بیا به د قربانۍ ځای دومره سپېڅلی شي چې هرڅوک یا هر شی چې د هغه سره ولګیږي، هغه به هم سپېڅلی شي.', 'اووه ورجې دا کار وکره. بیا به د قربانی جای دومره سپېچلی شی چې هرچوک یا هر شی چې د هغه سره ولګیزی، هغه به هم سپېچلی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33567, 'Exodus 29:38', 'Exodus', 29, 38, 'ته باید هره ورځ د قربانۍ په ځای باندې دوه یو کلن وري قرباني کړې.', 'ته باید هره ورج د قربانی په جای باندې دوه یو کلن وری قربانی کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33568, 'Exodus 29:39', 'Exodus', 29, 39, 'یو په سهار کې قرباني کړه او بل په ماښام کې.', 'یو په سهار کې قربانی کره او بل په ماشام کې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33569, 'Exodus 29:40', 'Exodus', 29, 40, 'د لومړني وري سره یو کیلو ګرام ښه اوړه وړاندې کړه چې یو لیتر سوچه د زیتونو تېل ورسره ګډ وي او د څښلو د نذرانې په توګه یو لیتر شراب هم وړاندې کړه.', 'د لومرنی وری سره یو کیلو ګرام شه اوره وراندې کره چې یو لیتر سوچه د زیتونو تېل ورسره ګد وی او د چشلو د نذرانې په توګه یو لیتر شراب هم وراندې کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_40.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33570, 'Exodus 29:41', 'Exodus', 29, 41, 'دوهم وری په ماښام کې قرباني کړه او د هغه سره هماغه اندازه اوړه، د زیتونو تېل او شراب وړاندې کړه لکه څنګه چې په سهار کې دې وکړل. دا زما دپاره یوه سوځېدونکې نذرانه ده او د هغې بوی په ما باندې ښه لګیږي.', 'دوهم وری په ماشام کې قربانی کره او د هغه سره هماغه اندازه اوره، د زیتونو تېل او شراب وراندې کره لکه چنګه چې په سهار کې دې وکرل. دا زما دپاره یوه سوجېدونکې نذرانه ده او د هغې بوی په ما باندې شه لګیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33571, 'Exodus 29:42', 'Exodus', 29, 42, 'دا سوځېدونکې نذرانه دې د تل دپاره هره ورځ د سپېڅلې خېمې د دروازې په خولې کې زما حضور ته وړاندې شي. زه به هلته د اسراییلو د خلکو سره لیدنه او کتنه وکړم او تا سره به خبرې وکړم.', 'دا سوجېدونکې نذرانه دې د تل دپاره هره ورج د سپېچلې خېمې د دروازې په خولې کې زما حضور ته وراندې شی. زه به هلته د اسراییلو د خلکو سره لیدنه او کتنه وکرم او تا سره به خبرې وکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_42.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33572, 'Exodus 29:43', 'Exodus', 29, 43, 'د اسراییلیانو سره به هم هلته لیدنه او کتنه وکړم او هغه ځای به زما د جلال په وسیله پاک شي.', 'د اسراییلیانو سره به هم هلته لیدنه او کتنه وکرم او هغه جای به زما د جلال په وسیله پاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33573, 'Exodus 29:44', 'Exodus', 29, 44, 'نو زه به خېمه او د قربانۍ ځای سپېڅلی کړم او هارون او د هغه زامن به د دې دپاره پاک کړم چې د کاهنانو په توګه زما خدمت وکړي.', 'نو زه به خېمه او د قربانی جای سپېچلی کرم او هارون او د هغه زامن به د دې دپاره پاک کرم چې د کاهنانو په توګه زما خدمت وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_44.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33574, 'Exodus 29:45', 'Exodus', 29, 45, 'بیا به زه د اسراییلو د خلکو په منځ کې اوسېږم او د هغوی خدای به یم.', 'بیا به زه د اسراییلو د خلکو په منج کې اوسېزم او د هغوی خدای به یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33575, 'Exodus 29:46', 'Exodus', 29, 46, 'هغوی به په دې پوه شي چې زه د هغوی څښتن خدای یم، چا چې هغوی له مصر څخه راوویستل، ترڅو د هغوی په منځ کې واوسېږم. زه د هغوی څښتن خدای یم.', 'هغوی به په دې پوه شی چې زه د هغوی چشتن خدای یم، چا چې هغوی له مصر چخه راوویستل، ترچو د هغوی په منج کې واوسېزم. زه د هغوی چشتن خدای یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_29_46.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33576, 'Psalms 20:1', 'Psalms', 20, 1, 'په سختۍ کې دې څښتن کاندي قبوله ستا دعا د یعقوب خدای دې ساتنه وکړي ستا', 'په سختی کې دې چشتن کاندی قبوله ستا دعا د یعقوب خدای دې ساتنه وکری ستا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33577, 'Psalms 20:2', 'Psalms', 20, 2, 'له خپل سپېڅلي ځای نه دې کومک واستوي تاته د صهیون له غره دې مرسته وکړي ستا', 'له خپل سپېچلی جای نه دې کومک واستوی تاته د صهیون له غره دې مرسته وکری ستا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33578, 'Psalms 20:3', 'Psalms', 20, 3, 'کړي رایادې دې ستا ټولې نذرانې کړي قبولې دې ستا ټولې سوځېدونکې قربانۍ', 'کری رایادې دې ستا تولې نذرانې کری قبولې دې ستا تولې سوجېدونکې قربانی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33579, 'Psalms 20:4', 'Psalms', 20, 4, 'کړي پوره دې هغه ستا د زړه ارمان او د ستا ټول پلانونه دې کامیاب کړي', 'کری پوره دې هغه ستا د زره ارمان او د ستا تول پلانونه دې کامیاب کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33580, 'Psalms 20:5', 'Psalms', 20, 5, 'بیا به چیغې د خوشحالۍ ستا په بریا کړو د خپل خدای په نوم به جګ کړو بیرغونه کړي څښتن دې ټول قبول ستا سوالونه', 'بیا به چیغې د خوشحالی ستا په بریا کرو د خپل خدای په نوم به جګ کرو بیرغونه کری چشتن دې تول قبول ستا سوالونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33581, 'Psalms 20:6', 'Psalms', 20, 6, 'اوس پوهېږم چې څښتن خپل غوره کړی پاچا ژغوري کړي دعا به یې قبوله له خپل پاک ځایه اسمانه ور به کړي په خپل قدرت هغه ته لویې کامیابۍ', 'اوس پوهېزم چې چشتن خپل غوره کری پاچا ژغوری کری دعا به یې قبوله له خپل پاک جایه اسمانه ور به کری په خپل قدرت هغه ته لویې کامیابی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33582, 'Psalms 20:7', 'Psalms', 20, 7, 'ځینې توکل کوي ګاډیو جنګي خپلو باندې ځینې توکل کړي په اسونو باندې زمونږ توکل دی په نامه د خپل څښتن خدای', 'جینې توکل کوی ګادیو جنګی خپلو باندې جینې توکل کری په اسونو باندې زمونز توکل دی په نامه د خپل چشتن خدای', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33583, 'Psalms 20:8', 'Psalms', 20, 8, 'داسې خلک به ښوییږي او رالویږي خو مونږه به پاڅېږو ټینګ ودرېږو به', 'داسې خلک به شوییزی او رالویزی خو مونزه به پاچېزو تینګ ودرېزو به', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33584, 'Psalms 20:9', 'Psalms', 20, 9, 'ای څښتنه، ته پاچا ته بری ورکړه د کومک دپاره زمونږه فریاد واوره', 'ای چشتنه، ته پاچا ته بری ورکره د کومک دپاره زمونزه فریاد واوره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_20_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33585, 'Proverbs 14:1', 'Proverbs', 14, 1, 'هوښیاره ښځه خپل کور ودانوي خو جاهله ښځه خپل کور په خپل لاس ورانوي.', 'هوشیاره شجه خپل کور ودانوی خو جاهله شجه خپل کور په خپل لاس ورانوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs014_verse_001.mp3', 'https://drive.google.com/file/d/1giaYh8e3wGyvLNWmEZuCsr0MfOYUfDHm/preview', 1761237837, 1761237837),
(33586, 'Proverbs 14:2', 'Proverbs', 14, 2, 'څوک چې له څښتن څخه وېریږي هغه په سمه لار ځي خو څوک چې په غلطو لارو روان وي څښتن سپکوي.', 'چوک چې له چشتن چخه وېریزی هغه په سمه لار جی خو چوک چې په غلطو لارو روان وی چشتن سپکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs014_verse_002.mp3', 'https://drive.google.com/file/d/1frYS9kWb3qcyC11p4w31c3xfVsaEr_V5/preview', 1761237837, 1761237837),
(33587, 'Proverbs 14:3', 'Proverbs', 14, 3, 'د جاهل له کبرجنې ژبې نه د سزا شنه لښته جوړیږي خو د هوښیارانو د خولې خبرې له هغوی ساتنه کوي.', 'د جاهل له کبرجنې ژبې نه د سزا شنه لشته جوریزی خو د هوشیارانو د خولې خبرې له هغوی ساتنه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs014_verse_003.mp3', 'https://drive.google.com/file/d/1queRxmRKlvSsaGX8ycAvTEW4Sr7ymH1U/preview', 1761237837, 1761237837),
